var file_map = map[string]string{

	"analyse_assets.baml":           "class AssetAnalysis {\n  description string @description(\"A one line description of what's in the image\")\n  tags string[] @description(\"add 3,4 tags which fits the most eg. dashboard, product-screen etc\")\n}\n\nfunction AnalyzeImage(image: image) -> AssetAnalysis {\n  client SmallBoyFastGemini\n  prompt #\"\n    Analyze the provided image in detail.\n\n    {{ ctx.output_format }}\n\n    {{ _.role(\"user\") }}\n    {{ image }}\n  \"#\n}\n",
	"animation_generator.baml":      "class GenerateAnimationCodeRequest {\n  Prompt string @description(\"Visual animation blueprint generated earlier\")\n  VideoBranding VideoBranding\n}\n\nclass GenerateAnimationCodeResponse {\n  code string @description(\"Typescript code\")\n  total_frames int @description(\"total frames for this animation at 30fps\")\n  manualEdits string? @description(\"valid json\")\n  thinkingSummary string? @skip()\n}\n\nfunction GenerateAnimation(input: GenerateAnimationCodeRequest, conversation_history: Message[]) -> GenerateAnimationCodeResponse | AskUserQuestion {\n  client CustomGeminiProPreview\n  prompt #\"\n    You are an expert in generating React components for Remotion animations.\n\n    ## COMPONENT STRUCTURE\n\n    1. Start with ES6 imports\n    2. Export as: export default function RemoteComponent() { ... }\n    3. Component body order:\n       - DEFAULT_DATA\n       - Multi-line comment description (2-3 sentences)\n       - Hooks (useCurrentFrame, useVideoConfig, etc.)\n       - Constants (COLORS, TIMING, LAYOUT) - all UPPER_SNAKE_CASE\n       - Calculations and derived values\n       - return JSX\n\n    ## LAYOUT RULES\n\n    - Use the full canvas with explicit dimensions from `useVideoConfig()`.\n    - Use full width of the canvas with appropriate padding.\n    - Never constrain content to a small centered webpage-like box.\n    - **Keep layouts responsive and readable: use sufficient `lineHeight` to prevent overlap or overflow.**\n    - Do not measure DOM elements or text dimensions for layout or responsiveness.\n    - Prefer CSS layout techniques (flexbox, grid, wrapping, scaling) over measuring content dimensions.\n\n    {% raw %}\n    ```tsx\n\n    ### Never generate\n\n    ```tsx\n    flex: 1\n    ```\n\n    ```tsx\n    width: \"100%\"\n    height: \"100%\"\n    ```\n\n    ```tsx\n    width: \"100vw\"\n    height: \"100vh\"\n    ```\n    {% endraw %}\n\n    Treat Remotion like a fixed-size animation canvas, not a responsive webpage.\n\n    {{ ConstantsRules() }}\n\n    ## AVAILABLE IMPORTS\n\n   - You may import any icon from `lucide-react` if needed.\n\n   {% raw %}\n    \\`\\`\\`tsx\n    import { useCurrentFrame, useVideoConfig, interpolate, spring, Sequence, Easing, random } from \"remotion\";\n    import { Audio } from '@remotion/media';\n    import { useState, useEffect } from \"react\";\n    import { Text, LogoAsset, IconAsset, useTheme, MediaAsset, parseText } from './';\n\n    const DEFAULT_DATA = {\n      title: \"AI Automation\",\n      subtitle: \"Save 10 hours per week\",\n      icon: \"Bot\",\n      features: [\n        {\n          title: \"Automation\",\n          icon: Heart,\n        },\n        {\n          title: \"Tool\",\n          icon: \"icon:google-drive\",\n        },\n      ],\n    };\n\n    export default function RemoteComponent() {\n    const { width, height, fps } = useVideoConfig();\n\n    {/* OTHER CONSTs */}\n    const FADE_DURATION = xx;\n    const PADDING = xx;\n\n    return (\n      <div\n        style={{\n          width,\n          height,\n          position: \"relative\",\n          overflow: \"hidden\",\n        }}\n      >\n        {/* animation */}\n      </div>\n    );\n    }\n    \\`\\`\\`\n   {% endraw %}\n\n    ## ANIMATION RULES\n\n    - Prefer spring() for organic motion (entrances, bounces, scaling)\n    - Use interpolate() for linear progress (progress bars, opacity fades)\n    - Always use { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" }\n    - Add stagger delays for multiple elements\n    - **Keep the overall animation fast, avoid long or empty frames between stagger delays**\n    - **Animate references by default; use them as attachments only when explicitly requested.**\n\n    ## Virtual Camera (optional)\n\n    - When beneficial(text animations, product showcases etc), animate a virtual camera instead of keeping the scene static.\n    - The camera may reframe, zoom, shift focus, and follow typed or revealed content to guide the viewer's attention.\n\n    ## RESERVED NAMES (CRITICAL)\n\n    NEVER use these as variable names - they shadow imports:\n    - spring, interpolate, useCurrentFrame, useVideoConfig, Sequence\n    **NEVER use any import outside the AVAILABLE IMPORTS, the build will fail**\n\n    ## STYLING RULES\n\n    - Use inline styles only\n    - **There is already background on the canvas.**\n    - **Don't add any background on the root, even if the reference image/video has it. Keep it transparent**\n\n    {{ AnimationPrimitives(input.VideoBranding) }}\n\n    {{ BrandUsageInstructions(input.VideoBranding) }}\n    {{ BrandGuidelines(input.VideoBranding) }}\n\n    {% if not input.VideoBranding.brandColors %}\n    ## TEMPLATING RULES\n\n    - Remember: you are generating a reusable animation template, not a one-off animation.\n    - **Design layouts to accommodate realistic variations in content length, arrays.**\n    - Text may wrap, reflow, resize, or use multiple lines when needed.\n    - Prefer CSS layout techniques (flexbox, grid, wrapping, scaling) over measuring content dimensions.\n    - Minor layout adjustments are preferred over text overflow, clipping, or overlap.\n    - Prioritize visual quality over extreme responsiveness.\n    - Treat `DEFAULT_DATA` like component props: it should contain only customizable content, not internal logic, styling, animation settings, or implementation details.\n    - Do NOT store element IDs, colors, React keys, or other implementation details in `DEFAULT_DATA`, use **array index for ids** if needed.\n\n    {% endif %}\n\n    ## ASK QUESTIONS RULES\n\n    Ask before proceeding if:\n    - If the prompt is ambiguous or visual details are unclear.\n    - You are unclear on a key decision which you want to clarify before proceeding\n    - You're not clear on what to animate.\n    - Use the **ask_user_question** tool — do not assume missing creative direction.\n\n    ## OUTPUT FORMAT (CRITICAL)\n\n     * Always return the **total frame count**, keeping it consistent with the scene timings and FPS. Avoid unnecessary idle or dead frames.\n     * If `manualEdits` are provided in follow-up requests, always return the updated `manualEdits` along with the updated code.\n     * `manualEdits` reference code and elements by `elementId`. If a code change removes or renames an element so its ID no longer exists, remove the corresponding entry from `manualEdits`.\n\n    ---\n    ## INPUT\n\n    Resolution and Canvas Size:\n    16x9(1920x1080)\n\n    FPS:\n    30\n\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }}\n    {{ message.content }}\n    {% if message.images and message.images|length > 0 %}\n    {{ message.images }}\n    {% endif %}\n    {% if message.videos and message.videos|length > 0 %}\n    {{ message.videos }}\n    {% endif %}\n    {% endfor %}\n    {% endif %}\n\n    ---\n    {{ ctx.output_format }}\n  \"#\n}",
	"clients.baml":                  "// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview\n\nclient<llm> CustomGeminiProPreview {\n  provider google-ai\n  retry_policy Exponential\n  options {\n    model \"gemini-3.1-pro-preview\"\n    api_key env.GOOGLE_API_KEY\n    generationConfig { thinkingConfig { includeThoughts true } }\n  }\n}\n\nclient<llm> SmallBoyFastGemini {\n  provider google-ai\n  retry_policy Exponential\n  options {\n    model \"gemini-2.5-flash-lite\"\n    api_key env.GOOGLE_API_KEY\n  }\n}\n\nclient<llm> SmallBoyFastGPT {\n  provider openai\n  retry_policy Exponential\n  options {\n    model \"gpt-4o-mini\"\n    api_key env.OPENAI_API_KEY\n  }\n}\n\nclient<llm> CustomClaudeOpus {\n  provider \"anthropic\"\n  retry_policy Exponential\n  options {\n    model \"claude-opus-4-6\"\n    api_key env.ANTHROPIC_API_KEY\n    max_tokens 12000\n    temperature 0.1\n  }\n}\n\nclient<llm> CustomOpenAI {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n  }\n}\n\nclient<llm> CustomOpenAI5 {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"medium\"\n    }\n  }\n}\n\nclient<llm> CustomOpenAI5WithThinkingSummary {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"medium\"\n      summary \"auto\"\n    }\n  }\n}\n\nclient<llm> CustomOpenAI55WithThinkingSummary {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.5\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"medium\"\n      summary \"auto\"\n    }\n  }\n}\n\nclient<llm> CustomOpenAI5WithLowThinkingSummary {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"low\"\n      summary \"auto\"\n    }\n  }\n}\n\n// https://docs.boundaryml.com/docs/snippets/clients/retry\nretry_policy Constant {\n  max_retries 3\n  strategy {\n    type constant_delay\n    delay_ms 200\n  }\n}\n\nretry_policy Exponential {\n  max_retries 2\n  strategy {\n    type exponential_backoff\n    delay_ms 300\n    multiplier 1.5\n    max_delay_ms 10000\n  }\n}",
	"common_helpers.baml":           "class Message {\n  role \"user\" | \"assistant\" | \"tool\"\n  content string\n  images image[]\n  videos video[]\n}\n\nenum AskUserQuestionType {\n  GENERIC @description(\"general clarification\")\n  UPLOAD_ATTACHMENT @description(\"when you need to ask user to upload\")\n}\n\nclass AskUserQuestion {\n  tool_name \"ask_user_question\" @description(\"Use this tool to ask the user a question when you need clarification or additional information\")\n  questionType AskUserQuestionType\n  question_text string @description(\"The question to ask the user. Keep it concise (8 words or less).\")\n  options string[] @description(\"The answer choices for the user to select from\")\n  allow_custom_entry bool? @description(\"Whether to allow custom text entry in addition to the predefined options\")\n  attachmentUrl string? @description(\"attachment to get the clarification\")\n}\n\nclass VideoBranding {\n  brandGuideLines string? @description(\"user provided brand guidelines\")\n  brandColors string? @description(\"user provided brand tokens\")\n  attachments string?\n}\n\nclass Scene {\n  element SceneElement\n  thinkingSummary string? @skip()\n}\n\nclass SceneElement {\n  component string\n  props string @description(\"required props in VALID JSON format as per the scene\")\n}\n\nenum ColorToken {\n  PRIMARY\n}\n\nclass Background {\n   solid ColorToken | string\n}",
	"common_prompts.baml":           "template_string BrandGuidelines(resume: VideoBranding) #\"\n    {% if resume.brandGuideLines %}\n    ### Brand Details:\n    {{ resume.brandGuideLines }}\n    {% endif %}\n\n    {% if resume.brandColors %}\n    ### Brand Colors:\n    {{ resume.brandColors }}\n    {% endif %}\n\n    {% if resume.attachments %}\n    ### Attachments:\n    {{ resume.attachments }}\n    {% endif %}\n\"#\n\ntemplate_string BackgroundGuidelines(branding: VideoBranding) #\"\n   ### Background Guidelines\n   Background is an optional property. Most scenes don't need it.\n   Only use available color tokens unless user has asked for it.\n\n   Rules:\n   - Only specify background for high-impact scenes or when changing sections/topic:\n     - Hook\n     - Key reveal\n     - Main insight\n   - Do NOT add background for filler, pacing, or transition scenes.\n   - Do NOT apply back to back scenes.\n   - Keep usage minimal and consistent across the video.\n\"#\n\ntemplate_string EnterAnimation(animation: AnimationCategories) #\"\n    {% if animation.entranceAnimations %}\n    ### Available Entrance Animations:\n    {% for anim in animation.entranceAnimations %}\n    - {{ anim }}\n    {% endfor %}\n\n    ### Instructions:\n    Select the prop entranceAnimation for scenes that support it.\n\n    Guidelines:\n    - Do NOT invent new animations. Only use the ones provided above.\n    - Do NOT select randomly. Choose based on the scene's intent and tone.\n    - Keep consistency: use at most 2–3 animation styles across the entire video.\n    - Match animation to purpose:\n      - Subtle / professional → zoomIn, slideUp, scaleIn, slideDown\n      - Reveal / arrival → zoomIn\n      - Sequential content → slideUp, slideLeft, slideRight\n      - Playful emphasis → zoomIn, elasticScale\n      - Dramatic / high impact → rotateIn\n    {% endif %}\n\"#\n\n\ntemplate_string ConstantsRules() #\"\n    ## CONSTANTS RULES (CRITICAL)\n\n    - Define exactly one module-level constant: `DEFAULT_DATA`.\n    - `DEFAULT_DATA` must be declared before the component.\n    - Store all customizable user-facing content in `DEFAULT_DATA`, including:\n      - Text\n      - Labels\n      - Placeholder Images (Except logo or logoIcon)\n      - Content-driven icons\n\n    - A content-driven icon is an icon whose meaning comes from the data being displayed and is expected to change when the content changes.\n      - Example: a list of categories where each category has its own icon.\n      - Example: feature cards with a matching icon for each feature.\n      - These icons MUST be stored in `DEFAULT_DATA`.\n      - Follow the icon format defined in the `### Icons` section.\n\n    - UI or functional icons are NOT user-facing content and should NOT be stored in `DEFAULT_DATA`.\n      - Example: submit button icon.\n      - Example: search icon inside an input.\n      - Example: close, menu, play, pause, next, previous, chevron, arrow, or navigation icons.\n      - These icons should be defined inline in JSX or as internal component logic.\n\n    - Never hardcode user-facing text or content-driven icons in JSX.\n    - Any constant other than `DEFAULT_DATA` must be declared inside the component body, after hooks.\n\n    This allows users to customize the animation by modifying only the content (text, images, and content-driven icons) without touching the implementation.\n\"#\n\ntemplate_string AnimationPrimitives(resume: VideoBranding) #\"\n\n    ## Typography\n    ### Text\n\n    - Use `Text` for all static text.\n    - Never use `span`, `p`, `h1-h6`, or other text elements.\n    - Every `Text` component MUST have an `id`.\n    - The `id` MUST start with `textasset-`, eg: `textasset-1`.\n\n    {% raw %}\n    ```tsx\n    <Text\n      id=\"textasset-1\"\n      text=\"Hello\"\n      style={{}}\n    />\n    ```\n    {% endraw %}\n\n    ### parseText()\n\n    - When text spans multiple lines or contains highlighted words, store it as a single `text` string and use `parseText()` to parse it.\n    - Use `\\n` for explicit line breaks.\n    - Wrap highlighted text in `{}`.\n    - Do not split text into arrays, words, or line objects in `DEFAULT_DATA`.\n    - Do not implement custom text parsing logic.\n    - `parseText()` preserves the original whitespace and returns an array of lines. Each line contains one or more text parts. Every part has:\n      - `text`: The text to render.\n      - `highlight`: Whether the text is highlighted.\n    - `parseText()` only parses the text. Decide independently how the parsed output should be laid out or animated based on the desired design.\n    - Preserve the original whitespace from `parseText()`. Render adjacent text parts as continuous inline text on the same baseline, without adding spacing (e.g. `gap`, margins, or padding) unless intentionally required by the animation.\n\n    {% raw %}\n    ```tsx\n    const DEFAULT_DATA = {\n      title: \"Launch {AI}\\nwith {Remotion}\",\n    };\n\n    const lines = parseText(DEFAULT_DATA.title);\n\n    {lines.map((line, lineIndex) => (\n      <div\n        key={lineIndex}\n        style={{\n          display: \"flex\",\n          alignItems: \"baseline\",\n        }}\n      >\n        {line.map((part, partIndex) => (\n          <Text\n            key={partIndex}\n            id={`textasset-${lineIndex}-${partIndex}`}\n            text={part.text}\n            style={{\n              color: part.highlight\n                ? theme.colors.primary\n                : theme.colors.foreground,\n            }}\n          />\n        ))}\n      </div>\n    ))}\n    ```\n    {% endraw %}\n\n    ## Image, Video, Icon and Logo:\n    - Never use `img`, `video` or other media tags\n    - Use LogoAsset for logos.\n    - Use MediaAsset for image or video.\n    - Every `LogoAsset`, `MediaAsset` component MUST have an `id` which start with `iconasset-`, `logoasset-`, `mediaasset-` respectively.\n    - Examples: `iconasset-1`, `logoasset-1`, `mediaasset-1`.\n\n    {% raw %}\n    ```tsx\n     <LogoAsset\n       id=\"logoasset-1\"\n       src=\"https://placehold.co/200x80.png\"\n       width={200}\n       height={80}\n       style={{}}\n     />\n     <MediaAsset\n        id=\"mediaasset-1\"\n        src=\"https://placehold.co/200x80.png\"\n        width={1200}\n        height={800}\n        style={{}}\n      />\n     ```\n    {% endraw %}\n\n    ## Icons\n\n    - Always render icons using `IconAsset`.\n    - If the icon exists in `lucide-react`, import it and pass the icon component to the `Icon` prop.\n    - If it does not exist in `lucide-react`, use a string in the format `icon:<icon-name>` (e.g. `icon:google`, `icon:aws`, `icon:google-drive`).\n    - Every `IconAsset` must have a unique `id` prefixed with `iconasset-`.\n    - The `Icon` prop accepts:\n      * A Lucide icon component\n      * A Lucide icon name as a string (e.g. `\"Heart\"`)\n      * A custom icon string in the format `icon:<icon-name>`\n    - Never use URLs, CDN links, jsDelivr links, or namespaced icon formats such as `simple-icons:*`, `mdi:*`, or `logos:*`.\n\n    Examples:\n    {% raw %}\n    ```tsx\n    import { Heart } from \"lucide-react\";\n\n    <IconAsset\n      id=\"iconasset-1\"\n      Icon={Heart} or {\"Heart\"} or {\"icon:aws\"}\n      size={48}\n      style={{}}\n    />\n    ```\n    {% endraw %}\n\n    ## Sound Effects (optional)\n    - Use **only** these built-in sound effects when they meaningfully enhance the animation:\n    - `mouse-click.wav` (clicks)\n    - `whoosh.wav` or `whip.wav` (swipe, or reveal). Use them sparingly and synchronize them with the visual event.\n    - Limit sound effects to at most 3 per scene, never use it in loops or maps. (MOST CRITICAL)\n\n    ```tsx\n    <Sequence from={eventFrame}>\n      <Audio src=\"https://remotion.media/mouse-click.wav\" />\n    </Sequence>\n    ```\n\"#\n\ntemplate_string BrandUsageInstructions(resume: VideoBranding) #\"\n    ### Branding\n    Use `useTheme()` hook for all brand colors and assets at runtime.\n\n    {% if resume.brandColors %}\n    Available brand information:\n    - Brand details: `<brand_details>`\n    - Brand tokens/colors: `<brand_tokens>`\n    - Brand assets: `<attachments>`\n\n    Use the provided brand details and tokens to understand the visual identity and make design decisions (e.g. contrast, emphasis, hierarchy),\n    but always reference colors and assets through `theme` in generated code.\n    {% else %}\n    Ensuring the animation works across different themes and backgrounds.\n    Hardcode only neutral surface/background colors when necessary (e.g. cards, panels), and ensure sufficient contrast and visibility for all elements.\n    {% endif %}\n\n    ```tsx\n    const theme = useTheme();\n\n    // Colors\n    theme.colors.foreground // Primary text\n    theme.colors.primary    // Primary accent/highlight\n    theme.colors.secondary  // Secondary accent\n\n    // Assets\n    theme.logo.url // use it to show bigger logo\n    theme.logo.width\n    theme.logo.height\n\n    theme.logoIcon.url // use it show the icon of the brand\n    theme.logoIcon.width\n    theme.logoIcon.height\n    ````\n\n    Guidelines:\n\n    * Use `theme.colors.foreground` for text. If contrast is insufficient, choose a readable alternative.\n    * Use `theme.colors.primary` for highlights, emphasis, and primary actions.\n    * Use `theme.colors.secondary` for supporting accents and secondary UI elements.\n    * Use `theme.logo` for full branding and `theme.logoIcon` for compact/icon-only branding.\n    * Render logos/icons with `LogoAsset` using `theme.logo.url` or `theme.logoIcon.url`.\n    * Only include logos/icons when they meaningfully support the animation.\n    * If an image or video is provided, prioritize its color palette over brand colors when appropriate.\n\n    {% if not resume.brandColors %}\n    ### Visibility & Contrast\n\n    * When using hardcoded surfaces (cards, panels, badges, overlays, etc.), ensure all content on that surface has sufficient contrast.\n    * Do not assume `theme.colors.foreground` will be readable on a hardcoded surface.\n    * If a hardcoded surface could conflict with theme colors (e.g. a white card and a light foreground color), use hardcoded foreground/icon colors that remain clearly visible.\n    * Always design surfaces and their contents together: if the background is hardcoded, choose content colors that guarantee readability regardless of the active theme.\n\n    ### Placeholders\n\n    - Use placeholders only in the format: `https://placehold.co/{width}x{height}.png`\n    - Replace `{width}` and `{height}` with numeric dimensions.\n    - Do not append colors, text, query parameters, paths, or any additional URL segments.\n    - Do not use external image URLs, Unsplash, logos, CDNs, or stock image services.\n    {% endif %}\n    ```\n\"#\n",
	"generators.baml":               "// This helps use auto generate libraries you can use in the language of\n// your choice. You can have multiple generators if you use multiple languages.\n// Just ensure that the output_dir is different for each generator.\ngenerator target {\n    // Valid values: \"python/pydantic\", \"typescript\", \"go\", \"rust\", \"ruby/sorbet\", \"rest/openapi\"\n    output_type \"go\"\n\n    // Where the generated code will be saved (relative to baml_src/)\n    output_dir \"../\"\n\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\n    // The BAML VSCode extension version should also match this version.\n    version \"0.218.1\"\n\n    // 'baml-cli generate' will run this after generating go code\n    // This command will be run from within $output_dir/baml_client\n    on_generate \"gofmt -w . && goimports -w .\"\n\n    // Your Go packages name as specified in go.mod\n    // We need this to generate correct imports in the generated baml_client\n    client_package_name \"github.com/shank318/coasterai\"\n}\n",
	"match_categories.baml":         "class Category {\n  name string\n  description string\n}\n\nclass MatchCategoriesRequest {\n  categories Category[]\n  content string\n  edits string?\n}\n\nclass MatchCategoriesResponse {\n  categories string[]\n}\n\nfunction MatchCategories(resume: MatchCategoriesRequest) -> MatchCategoriesResponse {\n  client SmallBoyFastGPT\n  prompt #\"\n    You are a content classification engine.\n\n    Analyze the final intended message of the scene.\n\n    Use the original scene JSON and, if provided, the user edits. User edits override the original content.\n\n    Categories:\n    {% for category in resume.categories %}\n    - {{ category.name }}: {{ category.description }}\n    {% endfor %}\n\n    Tasks:\n\n    1. Understand the final message being communicated.\n    2. Evaluate all provided categories.\n    3. Rank the categories from best match to worst match.\n\n    Rules:\n\n    - Consider every category.\n    - Always Return **ALL CATEGORIES* ordered by relevance.\n    - The first category must be the strongest match.\n    - Categories should be ranked relative to each other.\n    - Do not explain your reasoning.\n\n    Scene Content:\n    {{ resume.content }}\n\n    --------------------------------------------------\n    OUTPUT FORMAT\n    --------------------------------------------------\n\n    {{ ctx.output_format }}\n  \"#\n}",
	"scene_planner.baml":            "class AnimationCategories {\n  entranceAnimations string[]\n}\n\nclass VideoGenerationPlanRequest {\n    Duration int\n    Prompt string\n    Language string\n    Resolution string\n    VideoBranding VideoBranding\n    ComponentList string\n    AnimationCategories AnimationCategories\n}\n\nclass SceneSection {\n  name string @description(\"name of the section, around one or two words\")\n  slides Scene[]\n}\n\nclass GeneratedVideoPlan {\n    videoName string @description(\"name of the video, around 5 to 15 length\")\n    sections SceneSection[]\n    thinkingSummary string? @skip()\n}\n\nfunction GeneratePlan(input: VideoGenerationPlanRequest, conversation_history: Message[]) -> GeneratedVideoPlan {\n  client CustomOpenAI5WithThinkingSummary\n  prompt #\"\n    You are a cinematic video planning director. Your job is to decompose a video brief into a sequence of scenes.\n    You decide WHAT appears in each scene, HOW it behaves, and WHAT data it shows.\n    You do NOT write code.\n\n    ## VIDEO STRUCTURE\n\n    A good product video follows these sections. Map the user's script to these sections before planning scenes:\n\n    - **Hook/Intro** — grab attention immediately..\n    - **Problem** — articulate the pain point the product solves.\n    - **Solution** — introduce the product as the answer.\n    - **Product/Benefit Info** — show specific features, workflows, or how it works. This section can breathe.\n    - **Social Proof** — logos, metrics, testimonials that build trust.\n    - **CTA** — what to do next.\n\n    {{ input.ComponentList }}\n\n    ## SCENE DESIGN PRINCIPLES\n\n    - One idea per scene. Never combine two components in one scene.\n    - All scenes should feel connected, forming a continuous flow that maintains visual rhythm and tone.\n    - NEVER duplicate the same text across scenes\n    - Always use Logo scenes to introduce/revel the brand and the supporting text before the scene.\n    - Always finish with CTA scene.\n    - **Target 15–20 scenes total when possible, but avoid forcing unnecessary scenes and force fitting. Distribute across sections naturally based on\n      how much the script emphasizes each section. Do not pad sections artificially.**\n\n    Fillers work in any section. Use them to:\n    - Develop an idea within a section with scenes\n    - Add pacing between scenes\n    - Fill out scene count when a section needs more depth\n    - **When an appropriate scene is not available**\n\n    ## SCENE SELECTION\n\n    - Choose scenes/fillers based on how well they visually communicate each script segment.\n    - Select scenes using both section tags and underlying script meaning.\n    - *DO NOT repeat scenes.*\n    - *DO NOT force-fit scenes. Use a scene only if it supports the script visually and contextually.*\n    - Use `<attachments>` for image or video scenes. Use placeholders only when no attachments are provided.\n    - Divide/Split script text into scenes at logical sentence breaks. Do not split mid-sentence.\n        **Good**\n        * `AI is changing how teams work`\n        * `Most workflows are still manual`\n        **Bad**\n        * `AI is changing`\n        * `how teams work`\n\n    ### Data\n    Define scene props in `SceneElement` using JSON format.\n    - Use placeholder values when actual data is unavailable.\n    - Remove trailing commas, periods, and special characters from text.\n    - Never ever place large text blocks in a single scene. Limit each scene to:\n        **Max 2 lines**\n        **Max 10 words**\n        **50–55 characters maximum**\n    - For image or video placeholders, use: `https://placehold.co/{width}x{height}.png` where `width` and `height` are pixel values.\n\n    ## Special Scenes and Their Props\n\n    Some scenes use pre-existing, non-responsive templates.\n\n    - Sample prop values are examples only. They define the expected schema, format, and content style—not the literal content.\n    - Preserve the props schema exactly. Do not add, remove, or rename fields.\n    - Preserve array lengths exactly.\n    - Generate replacement values that match the format and style of the sample values.\n    - Preserve the visual footprint of the content as closely as possible (e.g. word count, text length, number of lines, item counts). These templates are non-responsive, so significantly longer or shorter content may overflow or break the layout.\n\n    Examples:\n    - If a sample array contains 10 items, generate exactly 10 items.\n    - If each sample label contains 1–2 words, generate labels of similar length.\n    - If a field contains a short headline, generate a short headline—not a paragraph.\n    - If a field contains a date, currency, percentage, or statistic, generate a replacement in the same format.\n\n    Text Formatting Conventions:\n    If a text prop contains formatting markers, eg. { \"title\": \"Launch {AI}\\nWith {Remotion}\" }:\n    - `\\n` represents a line break. Preserve the line-break structure whenever possible.\n    - `{text}` marks text that should be highlighted. Replace only the text inside the braces while preserving the `{}` markers.\n\n    ## PLAN BEFORE EXECUTING\n\n    Before outputting scenes, reason through:\n\n    1. **Section mapping** — map or break the script into the appropriate sections?\n       Quote the relevant script portion for each section found.\n    2. Then break each video section further into multiple scenes or fillers.\n    3. **Narrative arc** — does the section order tell a coherent story?\n    4. **Hero vs supporting scenes** — which scenes carry the main message vs add pacing?\n    5. **Assets** — do any attachments match scene intent?\n    6. Use <attachments> and <user_note> to decide which attachment to use with Asset components.\n       pass the url as per props shape.\n\n    Only begin output after forming a clear plan.\n\n    ---\n\n    ## EXAMPLE SCENES\n    ```json\n    [\n      {\n        \"element\":\n          {\n            \"component\": \"AnimatedNumber\",\n            \"props\": \"{\\\"startText\\\": \\\"Solving\\\", \\\"endText\\\": \\\"incidents\\\", \\\"from\\\": 0, \\\"to\\\": 100}\"\n          }\n      },\n      {\n         \"element\":\n          {\n            \"component\": \"AnimatedImage\",\n             \"props\": \"{\\\"src\\\": \\\"@generated/ectplz/0.png\\\"}\"\n           }\n       }\n    ]\n    ```\n\n    {{ BrandGuidelines(input.VideoBranding) }}\n\n    {{ EnterAnimation(input.AnimationCategories) }}\n\n    ---\n\n    ## INPUT\n    Video FPS: 30 frames/second\n    Language: {{ input.Language }}\n\n    ### Script:\n    {{ input.Prompt }}\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    {{ ctx.output_format }}\n  \"#\n}",
	"script_planner.baml":           "class ScriptPlannerRequest {\n    Duration int\n    Prompt string\n    Language string\n    Resolution string\n    VideoBranding VideoBranding\n}\n\nenum VideoSection {\n  @@dynamic\n}\n\nclass ScriptSection {\n name VideoSection\n narration string[]\n}\n\nclass Script {\n  sections ScriptSection[]\n  thinkingSummary string? @skip()\n}\n\nclass GenerateScriptPlan {\n  plan (Script | AskUserQuestion[])\n}\n\nfunction GenerateScript(input: ScriptPlannerRequest, conversation_history: Message[]) -> GenerateScriptPlan {\n  client CustomOpenAI5WithThinkingSummary\n  prompt #\"\n    You are an expert video script strategist.\n\n    Your only goal is to transform the user's idea into a complete, production-ready video script.\n\n    Do NOT think about scenes, animations, templates, visuals or code.\n    Another agent will later decide how each narration is visualized.\n\n    ## YOUR TASK\n\n    The user may provide:\n    - a rough idea\n    - bullet points\n    - product information\n    - documentation\n    - a partially written script\n    - a complete script\n    - any combination of the above\n\n    Your job is to gather just enough information to produce an excellent script.\n    **Never invent important facts.**\n\n    ## CONVERSATION FLOW\n\n    The objective is to ask only for information that is genuinely missing.\n\n    1. Carefully analyze the user's prompt and the conversation history.\n    2. Extract everything the user has already provided.\n    3. Identify only the missing information that would materially improve the script.\n    4. Do NOT ask for information that is already available or can be reasonably inferred.\n    5. Ask multiple missing questions together whenever possible to minimize back-and-forth.\n\n    If the user's input already appears to be a complete or mostly complete script:\n    - Ask whether the script should be followed exactly, or whether you may make light improvements for clarity, pacing and flow.\n    - Do not rewrite the script until the user answers.\n\n    If enough information is already available, generate the script immediately without asking unnecessary questions.\n\n    Only return a Script once all required information has been collected.\n\n    The generated script will be shown to the user for review. The user must confirm or request changes before the video generation process continues.\n\n    ## SCRIPT REQUIREMENTS\n\n    The script should be organized into logical sections.\n    Use only the sections that improve the story. Add, remove or merge sections when appropriate.\n    Each section contains an ordered list of narration blocks.\n\n    Each narration block must:\n    - represent one complete idea\n    - sound natural as voiceover\n    - be understandable without surrounding context\n    - be concise (typically 1–3 sentences)\n    - contain enough semantic detail for another agent to retrieve relevant animation templates\n\n    The narration should describe WHAT is being communicated, not HOW it should be animated.\n\n    Good:\n    - \"Switching between five different dashboards wastes hours every week.\"\n    - \"Our AI automatically converts every blog post into engaging social media videos.\"\n\n    Bad:\n    - \"Zoom into the dashboard.\"\n    - \"Animate the logo from the left.\"\n    - \"Show a typing animation.\"\n\n    ## Attachments\n    - If available, You can use <attachments> details to improve the script.\n\n    ## ASK QUESTIONS WHEN NEEDED\n\n    Examples of information that may be worth asking about:\n    - target audience\n    - product or brand name\n    - primary goal\n    - approximate video duration\n    - call-to-action\n    - missing product details\n    - missing benefits\n    - unclear messaging\n    - any ambiguity that would materially affect the script\n    - Attachment is provided but usage is unclear: use **ATTACHMENT_CLARIFICATION**.\n\n    Never ask about information that the user has already provided.\n\n    ## INPUT\n    Language: {{ input.Language }}\n    Video Duration: 30-45 second\n    {{ BrandGuidelines(input.VideoBranding) }}\n\n    ### User provided prompt/script:\n    {{ input.Prompt }}\n\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    {{ ctx.output_format }}\n  \"#\n}",
	"template_props_extractor.baml": "class ExtractTemplateConfigRequest {\n  content string\n  scenes SceneElement[]\n  VideoBranding VideoBranding\n}\n\nclass ExtractTemplateConfigResponse {\n  scenes SceneElement[]\n}\n\nfunction ExtractTemplateConfig(input: ExtractTemplateConfigRequest) -> ExtractTemplateConfigResponse {\n  client SmallBoyFastGPT\n  prompt #\"\n    You are an expert at populating component props from the provided Scene Content and Brand Details.\n\n    Your task is to generate prop values for each component using the provided component schemas.\n    component are templates of animations with their props.\n\n    ## Props Rules\n\n    Props must be returned as a JSON-encoded string.\n    The JSON encoded in props must exactly match the structure of the provided Props Schema, including arrays, objects, nesting, and field names.\n\n    Never:\n    - convert arrays to objects\n    - convert objects to arrays\n    - change nesting\n\n    ## Value Generation\n\n    Populate props values using:\n    1. Scene Content\n    2. Brand Details (Only when needed, eg the prop field mention brandName, tagline etc)\n    3. If a value is a placeholder url, don't replace it. Keep it as it is.\n\n    ## Special components and Their Props\n    Some components use pre-existing, non-responsive templates and hence their props has sample values.\n    - Sample prop values are examples only. They define the expected schema, format, and content style—not the literal content.\n    - Preserve the props schema exactly. Do not add, remove, or rename fields.\n    - Preserve array lengths exactly.\n    - Generate replacement values that match the format and style of the sample values.\n    - Preserve the visual footprint of the content as closely as possible (e.g. word count, text length, number of lines, item counts). These templates are non-responsive, so significantly longer or shorter content may overflow or break the layout.\n\n    Examples:\n    - If a sample array contains 10 items, generate exactly 10 items.\n    - If each sample label contains 1–2 words, generate labels of similar length.\n    - If a field contains a short headline, generate a short headline—not a paragraph.\n    - If a field contains a date, currency, percentage, or statistic, generate a replacement in the same format.\n\n   Text Formatting Conventions:\n    If a text prop contains formatting markers, eg. { \"title\": \"Launch {AI}\\nWith {Remotion}\" }:\n    - `\\n` represents a line break. Preserve the line-break structure whenever possible.\n    - `{text}` marks text that should be highlighted. Replace only the text inside the braces while preserving the `{}` markers.\n\n    If a value cannot be determined from the scene content or brand details, generate a reasonable value that fits the context.\n\n    ## Assets\n\n    * Icons → `icon:<icon-name>`\n    * Images, logos, and media → use placeholders or provided brand assets\n    * Placeholder format:\n\n    ```text\n    https://placehold.co/{width}x{height}.png\n    ```\n\n    ## Component Constraints\n    Follow all field hints, ranges, defaults, and requirements defined in the component schema.\n\n    Scene Content:\n    {{ input.content }}\n\n    {{ BrandGuidelines(input.VideoBranding) }}\n\n    ## Component Schemas ({{ input.scenes|length }} total)\n\n    {% for scene in input.scenes %}\n    ### Component: {{ scene.component }}\n\n    Props Schema:\n    {{ scene.props }}\n\n    {% endfor %}\n\n\n    ## Critical Requirement\n    - Output scene count MUST be exactly {{ input.scenes|length }}.\n    - Generate exactly one output scene for each Component Schema above.\n    - Preserve the order of Component Schemas.\n    - Use the same component names.\n    - Never skip a component.\n    - Never generate additional components.\n    - Do not add or remove fields.\n    - Only modify values.\n\n   ---\n\n    ## OUTPUT FORMAT\n\n    {{ ctx.output_format }}\n  \"#\n}",
}

func getBamlFiles() map[string]string {
	return file_map
}
